'use strict';
// More stories, each with an in-depth account. Written for IQRA from the Qur'an, Sahih al-Bukhari, Sahih Muslim, other hadith
// collections where named, and the classical biographies (flagged "reported in the Sira").
DISCOVER.deep = DISCOVER.deep || {};
const addStory = (story, deep) => { DISCOVER.stories.push(story); if (deep) DISCOVER.deep[story.id] = deep; };

// ---------------------------------------------------------------- Prophets
addStory({ id: 'ishaq-yaqub', shelf: 'prophets', title: 'Ishaq and Ya\u2019qub', ar: 'إسحاق ويعقوب',
  p: ['Angels who visited Ibrahim brought him good news of a son, Ishaq, whose mother Sarah was elderly. Ishaq\u2019s son was Ya\u2019qub, also called Isra\u2019il, from whom Bani Isra\u2019il take their name, and whose twelve sons became its tribes.', 'Ya\u2019qub is remembered for his "beautiful patience" when Yusuf was lost, and for his last words to his sons: "What will you worship after me?"'],
  l: ['A promise from Allah can arrive when every ordinary expectation has gone.', 'Patience that does not complain to people, only to Allah, is "beautiful".', 'A believer\u2019s last concern is that his children keep the faith.'],
  v: [[11, 69, 73], [12, 84, 86], [2, 132, 133]], src: 'Qur\u2019an 11:69–73, 51:24–30, 12:84–86, 2:132–133' },
  { facts: [['Ishaq', 'Son of Ibrahim and Sarah, a prophet (19:49, 37:112–113)'], ['Ya\u2019qub', 'Son of Ishaq, also named Isra\u2019il; a prophet (19:49)'], ['His sons', 'Twelve, including Yusuf and Binyamin'], ['Praised for', 'Beautiful patience (sabrun jamil)'], ['His will', '"We will worship your God and the God of your fathers" (2:133)']],
    s: [
      { h: 'The guests', t: ['Angels came to Ibrahim in the form of men and greeted him, "Peace." He answered, "Peace," and soon brought a roasted calf. Seeing that their hands did not reach for it, he became wary of them. They said: "Do not fear. We have been sent to the people of Lut." His wife was standing there and laughed, and they gave her glad tidings of Ishaq, and after Ishaq, Ya\u2019qub (11:69–71).', 'She said: "Woe to me! Shall I give birth while I am an old woman and this, my husband, is an old man? Indeed, this is a strange thing!" They said: "Are you amazed at the decree of Allah? May the mercy of Allah and His blessings be upon you, people of the house. Indeed, He is Praiseworthy and Honourable." (11:72–73)'] },
      { h: 'The father of the tribes', t: ['Ya\u2019qub had twelve sons. The Qur\u2019an says that Ibrahim and Ya\u2019qub both left their children a testament: "O my sons, indeed Allah has chosen for you this religion, so do not die except while you are Muslims." (2:132) And as Ya\u2019qub lay dying: "Or were you witnesses when death approached Ya\u2019qub, when he said to his sons, What will you worship after me? They said: We will worship your God and the God of your fathers, Ibrahim and Isma\u2019il and Ishaq, one God. And we are Muslims [submitting] to Him." (2:133)', 'It is a clear statement that the prophets from Ibrahim on shared one religion, submission to Allah (Islam), and this is why the Qur\u2019an calls them all Muslims.'] },
      { h: 'The patience of Ya\u2019qub', t: ['When Yusuf was lost, then Binyamin, Ya\u2019qub said: "Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allah will bring them to me all together." And he turned away from them and said, "Oh, my sorrow over Yusuf," and his eyes became white from grief, and he was suppressing [his sorrow] (12:83–84). His sons said he would ruin his health. He said: "I only complain of my suffering and my grief to Allah, and I know from Allah that which you do not know." (12:86)', 'Then: "O my sons, go and find out about Yusuf and his brother and despair not of relief from Allah. Indeed, no one despairs of relief from Allah except the disbelieving people." (12:87) His patience was never a surrender of hope. The Prophet \uFDFA said that being patient is at the first shock; he wept when his son Ibrahim died, so crying is not against it.'] },
    ] });

addStory({ id: 'harun', shelf: 'prophets', title: 'Harun, the helper of Musa', ar: 'هارون',
  p: ['Musa asked Allah for his brother Harun as a minister because he was more eloquent. Harun was with him before Fir\u2019awn and was left in charge when Musa went to Mount Sinai.', 'While Musa was away, al-Samiri fashioned a calf from the people\u2019s jewellery and many worshipped it. Harun warned them and, when Musa returned in anger and seized his brother\u2019s head, said: "O son of my mother, the people overpowered me, and they were about to kill me."'],
  l: ['A good helper can be a greater gift than a good talent.', 'Leadership sometimes means choosing unity and caution over confrontation; Harun explained and Musa accepted.', 'Even the nearest to a prophet can be tested by his own people.'],
  v: [[20, 29, 36], [20, 90, 94]], src: 'Qur\u2019an 20:29–36, 20:85–97, 7:142–151' },
  { facts: [['Brother of', 'Musa, and older by some accounts'], ['Musa asked for him', '"Appoint for me a minister from my family: Harun, my brother" (20:29–30)'], ['Role', 'Prophet, spokesman, and deputy'], ['Hadith', '"You are to me as Harun was to Musa, except there is no prophet after me"'], ['Surahs', 'Ta-Ha, al-A\u2019raf, al-Shu\u2019ara\u2019']],
    s: [
      { h: 'A request', t: ['At the burning bush, Musa asked Allah to help his task: "My Lord, expand for me my breast [with assurance] and ease for me my task and untie the knot from my tongue that they may understand my speech. And appoint for me a minister from my family: Harun, my brother. Increase through him my strength and make him my partner in my task, that we may exalt You much and remember You much." (20:25–34) Allah said: "You have been granted your request, O Musa." (20:36)', 'And in Surah Maryam, Allah says: "And We gave him out of Our mercy his brother Harun as a prophet." (19:53) It is remembered as the greatest gift anyone has been given by another\u2019s dua.'] },
      { h: 'The calf', t: ['Musa left for the appointed meeting with Allah, and told Harun: "Take my place among my people and do right and do not follow the way of the corrupters." (7:142) The Samiri, a man among them, collected their jewellery, melted it and shaped it into a calf that lowed. He said: "This is your god and the god of Musa, but he forgot." (20:88) Harun told them: "O my people, you are only being tested by it, and indeed, your Lord is the Most Merciful, so follow me and obey my order." They said: "We will not cease to remain devoted to it until Musa returns to us." (20:90–91)'] },
      { h: 'Musa returns', t: ['Musa returned, angry and sorrowful, threw down the tablets and seized his brother by the head and pulled him toward him. Harun said: "O son of my mother, indeed the people oppressed me and were about to kill me, so let not the enemies rejoice over me and do not place me among the wrongdoing people." (7:150) In Surah Ta-Ha, he adds: "I feared that you would say, You caused division among the Children of Israel and did not observe my word." (20:94) Musa prayed: "My Lord, forgive me and my brother and admit us into Your mercy, and You are the most merciful of the merciful." (7:151)', 'The Prophet \uFDFA praised Harun\u2019s role when he told \u2018Ali on the way to Tabuk: "Are you not content to be to me as Harun was to Musa, except that there is no prophet after me?" (Sahih al-Bukhari and Sahih Muslim)'] },
    ] });

addStory({ id: 'habil-qabil', shelf: 'quran', title: 'The two sons of Adam', ar: 'ابنا آدم',
  p: ['Two sons of Adam each offered a sacrifice. Allah accepted one\u2019s and not the other\u2019s. The one rejected threatened to kill his brother. The righteous one said: "If you should raise your hand against me to kill me, I would not raise mine against you to kill you. Indeed I fear Allah." Then the brother killed him.', 'Not knowing what to do with the body, he watched a raven scratch the earth to show how to bury a body, and said: "Woe to me! Am I not able to be like this raven?" He was left among those full of regret.'],
  l: ['Allah accepts what is sincere; envy is blind to that.', 'Self-restraint is stronger than retaliation.', 'The Prophet \uFDFA said every unjust killing carries a share of sin for the first murderer, since he began the practice.'],
  v: [[5, 27, 31]], src: 'Qur\u2019an 5:27–32; Sahih al-Bukhari and Sahih Muslim (the first murder)' },
  { facts: [['Surah', 'Al-Ma\u2019idah (5:27–32)'], ['Names', 'Not given in the Qur\u2019an; tradition calls them Habil (Abel) and Qabil (Cain)'], ['Cause', 'Envy after an offering was accepted from one and not the other'], ['First', 'The first murder, and the first burial'], ['Hadith', '"No soul is killed unjustly except that the first son of Adam has a share of its blood" (Sahih al-Bukhari and Sahih Muslim)']],
    s: [
      { h: 'The offerings', t: ['"And recite to them the story of the two sons of Adam, in truth, when they both offered a sacrifice [to Allah], and it was accepted from one of them and was not accepted from the other. Said [the latter], I will surely kill you. Said [the former], Indeed, Allah only accepts from the righteous [who fear Him]." (5:27) The Qur\u2019an does not say what each offered or how acceptance was shown; the narrations are from earlier traditions. What matters is the reason given: acceptance depends on taqwa.'] },
      { h: 'The brother\u2019s answer', t: ['"If you should raise your hand against me to kill me, I would not raise mine against you to kill you. Indeed, I fear Allah, Lord of the worlds. Indeed, I want you to obtain [thereby] my sin and your sin so you will be among the companions of the Fire. And that is the recompense of the wrongdoers." (5:28–29) Scholars explain that he did not mean to submit to being killed in all circumstances, but that he chose not to start violence against his own brother, even at his own cost, and that it was a statement of restraint before a crime, not a rule for self-defence.'] },
      { h: 'The raven', t: ['"And his soul permitted to him the murder of his brother, so he killed him and became among the losers. Then Allah sent a crow searching in the ground to show him how to hide the disgrace of his brother. He said: Woe to me! Have I failed to be like this crow and hide the disgrace of my brother? And he became of the regretful." (5:30–31)', 'His regret was not repentance: the verse says he became "of the regretful," not "of the repentant."'] },
      { h: 'The law drawn from it', t: ['Because of this, Allah says: "We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption [done] in the land, it is as if he had slain mankind entirely. And whoever saves one, it is as if he had saved mankind entirely." (5:32) The Prophet \uFDFA said: "No soul is killed unjustly except that the first son of Adam has a share of its blood, because he was the first to establish killing." (Sahih al-Bukhari and Sahih Muslim)'] },
    ] });

addStory({ id: 'saba', shelf: 'quran', title: 'The people of Saba\u2019 and the flood', ar: 'سبأ',
  p: ['The people of Saba\u2019 in Yemen lived between two gardens, one to the right and one to the left of their land. They were told to eat from their Lord\u2019s provision and to be grateful. They turned away.', 'Allah sent upon them the flood of the dam (sayl al-\u2018arim) and replaced their gardens with bitter fruit, tamarisk and a few lote trees. They had even asked that their journeys between towns be made longer.'],
  l: ['Gratitude keeps blessings; neglect lets them go.', 'A people can have beauty, safety and trade, and lose everything by arrogance.', '"Make longer the distances between our journeys" is a picture of discontent that has lost its gratitude.'],
  v: [[34, 15, 19]], src: 'Qur\u2019an 34:15–19' },
  { facts: [['Surah', 'Saba\u2019 (34:15–19)'], ['Place', 'Yemen, around Ma\u2019rib'], ['Blessing', '"A good land and a forgiving Lord"'], ['Punishment', 'The flood of al-\u2018Arim, the dam'], ['Proverb', '"They scattered like the people of Saba\u2019" (tafarraqu aydi Saba\u2019)']],
    s: [
      { h: 'A land of plenty', t: ['"There was for [the tribe of] Saba\u2019 in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], Eat from the provision of your Lord and be grateful to Him. A good land and a forgiving Lord." (34:15) Historians connect Saba\u2019 to the kingdom of southern Arabia that built a great dam at Ma\u2019rib to irrigate its fields. They also had safe, linked towns along the incense road: "And We placed between them and the cities which We had blessed [many] visible cities and determined between them the [length of] journey: Travel between them safely by night and day." (34:18)'] },
      { h: 'The turn', t: ['"But they turned away, so We sent upon them the flood of the dam and replaced their two gardens with two gardens having bitter fruit and tamarisk and something of sparse lote trees." (34:16) Then the Qur\u2019an adds what they said: "They said: Our Lord, lengthen the distance between our journeys, and wronged themselves. So We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful." (34:19)', 'Commentators describe how they became bored of easy journeys and wished for harder ones to appear more important, a kind of arrogance toward ease. When the dam gave way they scattered across Arabia; tribes that later appear in Madinah and the north, such as Aws and Khazraj, are said to be among their descendants.'] },
      { h: 'Reading it', t: ['The verse says the sign is for "everyone patient and grateful." The believer\u2019s state is exactly these two: patient in hardship, grateful in ease. The Prophet \uFDFA said: "How wonderful is the affair of the believer..." (Sahih Muslim), which applies the same pair to a life.'] },
    ] });

addStory({ id: 'cow', shelf: 'quran', title: 'The Cow of Bani Isra\u2019il', ar: 'البقرة',
  p: ['A man among Bani Isra\u2019il was found murdered and each party blamed another. Musa told them that Allah commands them to slaughter a cow. They answered, "Do you take us in ridicule?" Then they began asking questions: what kind, what colour, what age, until the description became so narrow that they found only one.', 'Allah told them to strike the dead man with a part of the cow, and the dead man was brought back to life (the commentaries say, to name his killer). The surah is named for this story.'],
  l: ['Obey the command as given. The more they questioned, the harder it became.', 'Allah shows how He gives life to the dead.', 'The Prophet \uFDFA warned against excessive questions, "for they were destroyed by their many questions" (Sahih Muslim).'],
  v: [[2, 67, 73]], src: 'Qur\u2019an 2:67–73' },
  { facts: [['Surah', 'Al-Baqarah (2:67–73), which is named after it'], ['Command', '"Allah commands you to slaughter a cow"'], ['Their mistake', 'Asking questions that narrowed the command'], ['Result', 'A dead man revived by a strike with part of the cow'], ['Point', 'Allah "shows you His signs that you might reason"']],
    s: [
      { h: 'The murder and the command', t: ['"And [recall] when you killed a man and disputed over it, but Allah was to bring out that which you were concealing. So We said, Strike him with part of it. Thus does Allah bring the dead to life, and He shows you His signs that perhaps you will understand." (2:72–73) The command, before this, was: "Indeed, Allah commands you to slaughter a cow." They said: "Do you take us in ridicule?" He said: "I seek refuge in Allah from being among the ignorant." (2:67)'] },
      { h: 'The questions', t: ['They said: "Call upon your Lord to make clear to us what it is." Musa said: "[Allah] says, It is a cow neither old nor virgin, but median between that." So do what you are commanded. They said: "Call upon your Lord to show us what is her colour." He said: "A yellow cow, bright in colour, pleasing to the observers." They said: "Call upon your Lord to make clear to us what it is. Indeed, all cows look alike to us. And indeed we, if Allah wills, will be guided." He said: "He says, It is a cow neither trained to plough the earth nor to irrigate the field, one free from fault with no spot upon her." They said: "Now you have come with the truth." And they slaughtered her, but they could hardly do it. (2:68–71)'] },
      { h: 'The lesson of the Prophet', t: ['Commentators note that had they slaughtered any cow when first told, they would have done it. The Prophet \uFDFA said: "Leave me as I leave you. Those before you were destroyed because of their many questions and their disagreements with their prophets. If I forbid you something, avoid it, and if I order you something, do as much of it as you can." (Sahih al-Bukhari and Sahih Muslim). This was a lesson on obedience and about how many a hardship is created by those who ask for details after the matter was clear.'] },
    ] });

addStory({ id: 'table', shelf: 'quran', title: 'The Table from Heaven', ar: 'المائدة',
  p: ['The disciples of \u2018Isa asked whether his Lord could send down a table from the sky. \u2018Isa told them to fear Allah if they were believers. They said they wished to eat from it, so their hearts would be at ease and they would know that he had told them the truth.', '\u2018Isa prayed, and Allah said He would send it down, with a warning: whoever disbelieves after it will receive a punishment that He has not given to anyone in the worlds.'],
  l: ['Asking for a sign after faith is a risk, because the responsibility becomes greater.', 'The dua of \u2018Isa asks that the day be an Eid and a sign: gratitude is a part of every blessing.', 'The surah is named after this table (al-Ma\u2019idah).'],
  v: [[5, 112, 115]], src: 'Qur\u2019an 5:112–115' },
  { facts: [['Surah', 'Al-Ma\u2019idah (5:112–115), named after it'], ['Who asked', 'The disciples (al-hawariyyun)'], ['Reason', '"That we may eat from it and our hearts be reassured"'], ['\u2018Isa\u2019s dua', '"That it may be for us a festival"'], ['Warning', 'A severe punishment for any who disbelieve afterwards']],
    s: [
      { h: 'The request', t: ['"[Mention] when the disciples said, O \u2018Isa, son of Maryam, can your Lord send down to us a table [spread with food] from the heaven? He said: Fear Allah, if you should be believers. They said: We wish to eat from it and to have our hearts reassured and to know that you have been truthful to us and be among its witnesses." (5:112–113) Their statement is difficult: "can your Lord" is understood by scholars as a request, not doubt, though \u2018Isa\u2019s answer shows he thought it a risky one.'] },
      { h: 'The dua', t: ['\u2018Isa, son of Maryam, said: "O Allah, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers." (5:114) Allah said: "Indeed, I will send it down to you, but whoever disbelieves afterwards from among you, then indeed will I punish him with a punishment by which I have not punished anyone among the worlds." (5:115)'] },
      { h: 'What happened afterwards', t: ['The Qur\u2019an does not say what the table contained or what became of the people after; its point is the statement of Allah\u2019s generosity and the seriousness of ingratitude after witnessing a sign. Later reports give details of loaves and fish, and a punishment of those who disbelieved, but they are not found in authentic hadith, so we leave them. The Qur\u2019an then turns to the scene on the Day of Resurrection when \u2018Isa is asked about what his followers said of him (5:116–118).'] },
    ] });

addStory({ id: 'ruined-town', shelf: 'quran', title: 'The man who passed a ruined town', ar: 'مر على قرية',
  p: ['A man passed a town whose roofs had fallen in and asked, "How will Allah give this life after its death?" Allah caused him to die for a hundred years, then raised him. He was asked how long he stayed, and said "a day or part of a day." He was told: "Rather, you remained a hundred years." Look at your food and drink, which has not changed, and at your donkey, which is bones.', 'Then Allah put flesh on the bones of the donkey before his eyes. The man said: "I know that Allah is over all things competent."'],
  l: ['Resurrection is a sign the Qur\u2019an returns to again and again.', 'Time is under Allah\u2019s control: food stayed fresh while the donkey decayed.', 'The questions of believers are answered by showing, not scolding.'],
  v: [[2, 259, 260]], src: 'Qur\u2019an 2:259–260' },
  { facts: [['Surah', 'Al-Baqarah (2:259)'], ['Who', 'The Qur\u2019an does not name him or the town'], ['Question', '"How will Allah bring this to life after its death?"'], ['Sign', 'The food unspoiled, the donkey revived'], ['Companion verse', 'Ibrahim and the four birds (2:260)']],
    s: [
      { h: 'The ruin', t: ['"Or [consider such an example] as the one who passed by a township which had fallen into ruin. He said: How will Allah bring this to life after its death? So Allah caused him to die for a hundred years; then He revived him. [Allah] said: How long have you remained? He said: I have remained a day or part of a day. [Allah] said: Rather, you have remained a hundred years. Look at your food and your drink; it has not changed with time. And look at your donkey; and We will make you a sign for the people. And look at the bones [of the donkey] how We raise them and then We cover them with flesh. And when it became clear to him, he said: I know that Allah is over all things competent." (2:259)'] },
      { h: 'His question', t: ['His words are not a denial but wonder. Commentators say they were a question to see how Allah would restore a population from a ruin, and that Allah answered by doing it to him. Commentators note that the Qur\u2019an does not identify him because the point is the sign. Some earlier traditions say he was \u2018Uzayr or Irmiya; neither is established.'] },
      { h: 'Ibrahim and the birds', t: ['Right after it, Ibrahim asks to see: "My Lord, show me how You give life to the dead." [Allah] said: "Have you not believed?" He said: "Yes, but [I ask] only that my heart may be satisfied." He said: "Take four birds and incline them to yourself, then put on each hill a portion of them; then call them; they will come to you in haste. And know that Allah is Exalted in Might and Wise." (2:260) The Prophet \uFDFA said: "We are more worthy of doubt than Ibrahim," meaning he asked not out of doubt, and that if Ibrahim doubted, we would have more reason (Sahih al-Bukhari and Sahih Muslim), explaining that the request was for greater certainty.'] },
    ] });

// ---------------------------------------------------------------- The Sira
addStory({ id: 'sira-arabia', shelf: 'sira', ord: 0, title: 'Arabia before the Prophet \uFDFA', ar: 'العرب قبل الإسلام', era: 'before 570 CE',
  p: ['To understand the Prophet\u2019s \uFDFA mission, you need to see the world he was born into: a tribal Arabia between two empires, with Makkah as a trading and religious centre, the Kaaba filled with idols, and a society known as the age of ignorance (jahiliyyah).', 'It was not without virtues, such as generosity, hospitality and bravery, but it was also a land of feuds, fortune-telling, interest, and the burying of daughters.'],
  l: ['The Qur\u2019an did not come into an empty world: it answered real problems.', 'Pure monotheism, the religion of Ibrahim, had survived among a few seekers (hanifs).', 'Every society has good it can build on and wrongs it must leave.'],
  v: [[106, 1, 4], [81, 8, 9]], src: 'Sira of Ibn Ishaq and Ibn Hisham; Qur\u2019an 106, 81:8–9' },
  { facts: [['Region', 'The Arabian Peninsula: Hijaz, Najd, Yemen, the Gulf coast'], ['Neighbours', 'The Byzantine and Persian empires, Abyssinia'], ['Makkah\u2019s trade', 'Winter caravans to Yemen and summer caravans to Syria (106:1–2)'], ['Religion', 'Idols around the Kaaba, alongside the memory of Ibrahim and a few hanifs'], ['Calendar', 'Four sacred months in which fighting was forbidden']],
    s: [
      { h: 'Tribes and honour', t: ['Society was organised by tribe and clan. A person\u2019s protection, identity and justice rested on their kin, which is why those without a strong tribe suffered so much when Islam came. Honour was guarded fiercely; a killing could lead to a blood feud lasting decades, such as the war of Basus between two tribes, or the Day of Bu\u2019ath that left Aws and Khazraj weary. Poetry was the highest art, and the markets of \u2018Ukaz held contests where poets recited. Language mattered, and that is why the Qur\u2019an\u2019s challenge to produce something like it was so pointed.'] },
      { h: 'Makkah and the Kaaba', t: ['Makkah lay in a barren valley, yet it flourished because it held the Kaaba and the well of Zamzam. Quraysh controlled both and the pilgrim trade; they were called "the people of Allah" and respected by all tribes. They made treaties with neighbouring peoples that allowed their caravans to run safely, a favour the Qur\u2019an reminds them of: "For the accustomed security of Quraysh, their accustomed security [in] the caravan of winter and summer, let them worship the Lord of this House, who has fed them, [saving them] from hunger and made them safe, [saving them] from fear." (106:1–4)', 'By then the House built by Ibrahim and Isma\u2019il was filled with idols. According to the Sira, \u2018Amr ibn Luhayy brought idols to Makkah from Syria; the Prophet \uFDFA said he saw him dragging his intestines in the Fire, because he was the first to dedicate animals to the idols (Sahih al-Bukhari). People worshipped al-Lat, al-\u2018Uzza and Manat, as well as Hubal, and saw them as intercessors. They still believed Allah created the heavens and the earth (29:61, 31:25), but addressed others for their needs.'] },
      { h: 'The wrongs', t: ['The Qur\u2019an describes what it came to correct: burying infant girls alive (81:8–9, 16:58–59), killing children for fear of poverty (17:31), interest and unjust treatment of orphans, and the exploitation of the weak. Gambling and drinking were common. There was no common authority. Slaves were bought and sold, and women had little protection under law.',
        'It was also a place of seekers. A few men, the hanifs, such as Waraqah ibn Nawfal and Zayd ibn \u2018Amr ibn Nufayl, rejected idols and sought the religion of Ibrahim; Zayd would lean on the Kaaba and say: "O Quraysh, none of you is on the religion of Ibrahim but me." (Sahih al-Bukhari)'] },
      { h: 'The empires', t: ['To the north, the Byzantines ruled Syria; to the east, the Sasanian Persians ruled Iraq and the Gulf. They were fighting a long and exhausting war during the Prophet\u2019s \uFDFA time, and the Qur\u2019an itself refers to a Byzantine defeat and the promise of a later victory: "The Romans have been defeated in the nearest land. But they, after their defeat, will overcome within three to nine years." (30:2–4) To the south, the kingdom of Himyar had fallen to Abyssinian rule, and then to Persian control. Arabia lay in the shadows of these powers, so unimportant to them that when Islam emerged they hardly noticed.'] },
    ] });

addStory({ id: 'sira-ifk', shelf: 'sira', ord: 15.5, title: 'The slander (al-Ifk)', ar: 'حادثة الإفك', era: 'Sha\u2019ban, 5 or 6 AH',
  p: ['On the return from the expedition of Banu al-Mustaliq, \u2018A\u2019ishah went to look for a lost necklace, and when she returned the caravan had left, thinking she was in her howdah. She waited, and a Companion, Safwan ibn al-Mu\u2019attal, found her and brought her to Madinah on his camel without a word.', 'The hypocrites, led by \u2018Abdullah ibn Ubayy, spread a lie about her. For about a month the Prophet \uFDFA and his household were in pain, until Allah revealed ten verses of Surah al-Nur declaring her innocent.'],
  l: ['Do not pass on what you cannot verify. Allah says: "When you heard it, why did not the believers think good of themselves?"', 'A slander can hurt a whole household and a community.', 'Allah\u2019s answer to patience and trust was a public revelation.'],
  v: [[24, 11, 20], [24, 22]], src: 'Qur\u2019an 24:11–20; Sahih al-Bukhari and Sahih Muslim (\u2018A\u2019ishah)' },
  { facts: [['When', 'After the expedition of al-Muraysi\u2019 (Banu al-Mustaliq), 5 or 6 AH'], ['Slanderers', '\u2018Abdullah ibn Ubayy led it; a few believers repeated it, including Mistah, Hassan and Hamnah'], ['Revelation', 'Surah al-Nur 24:11–20, and 24:22'], ['Duration', 'About a month'], ['\u2018A\u2019ishah\u2019s words', '"Patience is most fitting"']],
    s: [
      { h: 'The night', t: ['\u2018A\u2019ishah\u2019s own account (Sahih al-Bukhari and Sahih Muslim): the Prophet \uFDFA used to draw lots among his wives when he travelled, and on this journey it was her turn. She was carried in a covered howdah. On the return, near Madinah, as the army camped at night, she went to relieve herself and found that her necklace of Zafar beads had fallen. She went back to look for it. The men who carried the howdah, believing she was inside since she was light, lifted it and moved on.',
        'She came back to an empty camp, wrapped herself in her cloak and sat down, thinking they would come back for her. She fell asleep. Safwan ibn al-Mu\u2019attal, who had been lagging behind the army, saw her, recognised her, as he had seen her before the hijab was revealed, and said "Inna lillahi wa inna ilayhi raji\u2019un." She woke, covered her face, and he made his camel kneel for her to mount, and led it on foot till they reached the army at midday.'] },
      { h: 'The rumour', t: ['\u2018Abdullah ibn Ubayy was seen spreading the story, and some Muslims, including Hassan ibn Thabit, Mistah ibn Uthathah and Hamnah bint Jahsh, joined in the talk. \u2018A\u2019ishah fell ill after returning and was not aware of what was being said. She noticed only that the Prophet \uFDFA was less gentle than usual. When she went to her mother\u2019s house, she heard from a woman what people were saying, and her illness doubled. She wept for days and nights.',
        'The Prophet \uFDFA consulted \u2018Ali and Usamah. Usamah spoke well of her, and \u2018Ali said that Allah had not constrained him and that there were many other women; ask the servant girl Barirah. Barirah said: "By the One who sent you with the truth, I have seen nothing in her except that she is a young girl who falls asleep over the dough and the goat eats it." He asked Zaynab bint Jahsh, who said: "I protect my hearing and sight; I know nothing about her except good." Aisha said that Zaynab was her rival among the wives but Allah protected her through her piety.'] },
      { h: 'The pulpit and the dispute', t: ['The Prophet \uFDFA stood on the pulpit and asked: "Who will excuse me from a man who has harmed my family? By Allah, I know nothing but good about my family, and they have mentioned a man about whom I know only good." Sa\u2019d ibn Mu\u2019adh said that he would behead him if he were from Aws, and Sa\u2019d ibn \u2018Ubadah of Khazraj objected, and the tribes nearly came to blows, until the Prophet \uFDFA calmed them.'] },
      { h: 'The silence broken', t: ['He came to \u2018A\u2019ishah and said: "O \u2018A\u2019ishah, I have heard such and such about you. If you are innocent, Allah will declare your innocence; and if you have committed a sin, ask Allah\u2019s forgiveness and repent, for when a servant admits his sin and repents, Allah accepts his repentance." Her tears dried up. She asked her parents to answer for her; they said they did not know what to say. She said: "I know that you have heard this and it has settled in your minds. If I say I am innocent, and Allah knows I am innocent, you will not believe me. If I admit to something Allah knows I did not do, you will believe me. I can only say what Yusuf\u2019s father said: So patience is most fitting, and Allah is the One sought for help against what you describe." She turned over on her bed, and said: "I hoped Allah would show my innocence in a dream, but I did not think that revelation would be sent down about me."',
        'Before anyone left, the Prophet \uFDFA began to show the signs of revelation: sweat running down like pearls on a cold day. When it was over, he was smiling, and the first thing he said was: "O \u2018A\u2019ishah, Allah has declared your innocence." Her mother said, "Get up and go to him." She said: "By Allah, I will not get up to him, and I will not praise anyone but Allah." Then Allah revealed: "Indeed, those who came with falsehood are a group among you. Do not think it bad for you; rather it is good for you." (24:11) The ten verses continue to 24:20.'] },
      { h: 'Abu Bakr and Mistah', t: ['Abu Bakr had been supporting his poor relative Mistah ibn Uthathah. After Mistah spoke about \u2018A\u2019ishah, he swore he would never help him again. Allah revealed: "And let not those of virtue among you and wealth swear not to give [aid] to their relatives and the needy and the emigrants for the cause of Allah, and let them pardon and overlook. Would you not like that Allah should forgive you? And Allah is Forgiving and Merciful." (24:22) Abu Bakr said: "Yes, by Allah, I would like Allah to forgive me," and he resumed supporting Mistah, saying he would never stop it. (Sahih al-Bukhari and Sahih Muslim)',
        'The punishment of eighty lashes was applied to some of those who had publicly accused her (Sunan Abi Dawud and al-Tirmidhi), as the law of qadhf requires four witnesses (24:4).'] },
    ] });

addStory({ id: 'sira-delegations', shelf: 'sira', ord: 21.5, title: 'The Year of Delegations', ar: 'عام الوفود', era: '9–10 AH',
  p: ['After the conquest of Makkah and Tabuk, deputations arrived from across Arabia to meet the Prophet \uFDFA and accept Islam, so many that the ninth year was named the Year of Delegations. Surah al-Nasr describes it: "you see people entering the religion of Allah in multitudes."', 'He received them in the courtyard of the mosque, honoured them and taught them. He also sent men to teach and judge among them: Mu\u2019adh ibn Jabal and Abu Musa to Yemen, \u2018Ali, Khalid and others to different regions.'],
  l: ['When the Prophet \uFDFA gave the first call he was alone; within twenty years the Peninsula was Muslim.', 'The sending of Mu\u2019adh shows how the faith was taught gradually: first tawhid, then prayer, then zakah.', 'The year of victory was a year of humility.'],
  v: [[110, 1, 3]], src: 'Qur\u2019an 110; Sahih al-Bukhari and Sahih Muslim; Sira' },
  { facts: [['Year', '9 AH (630–631 CE), the Year of Delegations'], ['Largest', 'Thaqif of Ta\u2019if, Banu Tamim, \u2018Abd al-Qays, Himyar, Najran'], ['Hajj of 9 AH', 'Led by Abu Bakr; \u2018Ali announced the opening of Surah al-Tawbah'], ['Sent to teach', 'Mu\u2019adh and Abu Musa (Yemen), \u2018Ali (Yemen), Khalid (Najran)'], ['Surah', 'Al-Nasr (110)']],
    s: [
      { h: 'Thaqif of Ta\u2019if', t: ['After the siege of Ta\u2019if, \u2018Urwah ibn Mas\u2019ud al-Thaqafi, the man who had marvelled at the Companions at Hudaybiyyah, accepted Islam and went back to his people to call them. As he stood on his roof to invite them, he was shot and killed. Before dying, he forgave his killers and said it was a gift Allah had granted him. Later, in Ramadan 9 AH, the Thaqif sent a delegation to Madinah. They asked for conditions: that their idol al-Lat should be left for three years. The Prophet \uFDFA refused, then every year, then a month. They finally accepted, and asked to be excused from prayer. He said: "There is no good in a religion without prayer." (as reported in the Sira and Sunan Abi Dawud). He appointed their youngest member, \u2018Uthman ibn Abi al-\u2018As, who had asked to learn the Qur\u2019an, as their leader. Al-Mughirah ibn Shu\u2019bah was sent to demolish al-Lat.'] },
      { h: 'Banu Tamim and the pride of poets', t: ['The delegation of Banu Tamim arrived with their poet and orator and challenged the Muslims to a contest. The Prophet \uFDFA asked Thabit ibn Qays to answer their speaker, and Hassan ibn Thabit their poet. After listening to both, Tamim\u2019s chief al-Aqra\u2019 said: "By my father, their speaker is more eloquent than ours, and their poet more poetic." They accepted Islam. The Prophet \uFDFA honoured them with gifts.'] },
      { h: 'Teachers sent out', t: ['When he sent Mu\u2019adh ibn Jabal to Yemen, he told him: "You will come to a people from the People of the Book. Let the first thing you invite them to be the worship of Allah. When they know Allah, tell them that Allah has made five prayers obligatory on them in the day and night. When they do so, tell them that Allah has obligated zakah on them, taken from their rich and given to their poor. When they obey, then avoid taking the best of their wealth, and fear the supplication of the oppressed, for there is no veil between it and Allah." (Sahih al-Bukhari and Sahih Muslim)',
        'He also told Mu\u2019adh and Abu Musa: "Make things easy and do not make them difficult; give glad tidings and do not make people averse; and cooperate and do not differ." (Sahih al-Bukhari and Sahih Muslim)'] },
      { h: 'The Hajj of Abu Bakr', t: ['In Dhul-Qa\u2019dah 9 AH the Prophet \uFDFA sent Abu Bakr to lead the Hajj. Just after he left, the opening verses of Surah al-Tawbah (Bara\u2019ah) were revealed, ending the treaties with the idolaters who broke them and giving the others until their treaties ended. The Prophet \uFDFA sent \u2018Ali to announce it at Mina on the day of sacrifice. They announced that no idolater would perform Hajj after that year, and no one would circle the Kaaba naked (Sahih al-Bukhari and Sahih Muslim). The next year was the Prophet\u2019s \uFDFA Farewell Pilgrimage.'] },
    ] });

addStory({ id: 'sira-home', shelf: 'sira', ord: 23.1, title: 'The Prophet at home', ar: 'في بيته', era: 'Madinah',
  p: ['Those who knew him best, his family and his servants, are our best witnesses. \u2018A\u2019ishah said he used to be "in the service of his family", sewing his own clothes and mending his shoes, and when the prayer was called, he would go out.', 'He was gentle with children, spent time with his wives, joked, listened, and raced. And in his own words: "The best of you are the best to their families, and I am the best of you to my family." (Sunan al-Tirmidhi)'],
  l: ['Real character shows at home.', 'He did not think household work beneath a leader.', 'He loved and expressed it: he told people when he loved them.'],
  src: 'Sahih al-Bukhari, Sahih Muslim, Sunan al-Tirmidhi, Sunan Abi Dawud' },
  { facts: [['Wives', 'Khadijah, Sawdah, \u2018A\u2019ishah, Hafsah, Zaynab bint Khuzaymah, Umm Salamah, Zaynab bint Jahsh, Juwayriyah, Umm Habibah, Safiyyah, Maymunah'], ['Children', 'Al-Qasim, Zaynab, Ruqayyah, Umm Kulthum, Fatimah, \u2018Abdullah (with Khadijah); Ibrahim (with Maryam al-Qibtiyyah)'], ['Grandchildren', 'Al-Hasan, al-Husayn, Umamah and others'], ['Qur\u2019an', '"The Prophet is closer to the believers than themselves, and his wives are their mothers" (33:6)'], ['Home', 'Rooms of mud brick and palm branches beside the mosque']],
    s: [
      { h: 'In the service of his family', t: ['\u2018A\u2019ishah was asked what the Prophet \uFDFA did at home. She said: "He used to be in the service of his family, and when the time for prayer came, he would go out for prayer." (Sahih al-Bukhari). She also said: "He used to mend his sandals, sew his garment, and do what men do in their homes." (Musnad Ahmad, sound). He milked his sheep, patched his clothes and helped with household work.', 'He told the Muslims: "The best of you are the best to their families, and I am the best of you to my family." (Sunan al-Tirmidhi). He said: "The believers with the most complete faith are those with the best character, and the best of you are the best to their women." (Sunan al-Tirmidhi)'] },
      { h: 'Affection and humour', t: ['He raced \u2018A\u2019ishah and she beat him; later, when she had put on weight, he beat her and said, "This is for that." (Sunan Abi Dawud). On a feast day, when Abyssinians were playing with spears in the mosque, he stood so she could watch behind him, his cheek touching hers, until she was tired (Sahih al-Bukhari and Sahih Muslim). He said to her: "I know when you are pleased with me and when you are angry with me. When you are pleased, you say, No, by the Lord of Muhammad; when you are angry, you say, No, by the Lord of Ibrahim." She said, "Yes, by Allah, I only avoid your name." (Sahih al-Bukhari and Sahih Muslim)'] },
      { h: 'With his daughters and grandchildren', t: ['When Fatimah entered, he rose, kissed her and sat her in his place; when he entered, she rose and kissed him (Sunan Abi Dawud and al-Tirmidhi). He said: "Fatimah is a part of me; whoever angers her angers me." (Sahih al-Bukhari). He wept when Ruqayyah died, and said "Join our righteous predecessor \u2018Uthman ibn Maz\u2019un," and he comforted the women who cried. He carried his grandchildren in prayer, and his grandson Hasan climbing on his back during prostration made him prolong it, until the child got down (Sunan al-Nasa\u2019i).'] },
      { h: 'In grief', t: ['His son Ibrahim died as a baby. The Prophet \uFDFA took him in his arms, his eyes flowing with tears, and said: "The eyes shed tears and the heart grieves, but we say only what pleases our Lord. O Ibrahim, we are grieved by your parting." (Sahih al-Bukhari and Sahih Muslim). When the sun was eclipsed on the day of his death, people said it was for Ibrahim; the Prophet \uFDFA said: "The sun and moon are two signs of Allah; they do not eclipse for the death or life of anyone." (Sahih al-Bukhari and Sahih Muslim), correcting a mistaken belief in his own moment of grief.'] },
    ] });

addStory({ id: 'sira-routine', shelf: 'sira', ord: 23.2, title: 'A day in his life', ar: 'شمائل النبي', era: 'Madinah',
  p: ['He slept early, woke in the last third of the night and prayed until his feet were swollen. When \u2018A\u2019ishah asked why, since his past and future sins had been forgiven, he said: "Should I not be a grateful servant?"', 'His days were full of prayer, teaching, visiting the sick, resolving disputes, and time with his family. He ate simply, smiled often and never criticised food.'],
  l: ['The greatest man in history stayed the most grateful.', 'He lived simply by choice.', 'The Companions described him as always smiling.'],
  src: 'Sahih al-Bukhari, Sahih Muslim, Sunan al-Tirmidhi (Shama\u2019il)' },
  { facts: [['Night prayer', 'Eleven or thirteen rak\u2019ahs, long and slow'], ['Food', 'Never criticised food; if he liked it he ate, if not, he left it'], ['Sleep', 'On a mat of palm fibre that left marks on his side'], ['Smile', '"I never saw anyone smile more than the Messenger of Allah" (al-Tirmidhi)'], ['Prayer taught', 'Pray as you saw me praying']],
    s: [
      { h: 'The night', t: ['\u2018A\u2019ishah described how he prayed: "Do not ask how beautiful and long it was." He would stand until his feet cracked (swelled). She said to him: "Why do you do this when Allah has forgiven you your past and future sins?" He said: "Should I not be a grateful servant?" (Sahih al-Bukhari and Sahih Muslim). Hudhayfah prayed with him once and said that in a single rak\u2019ah, he recited al-Baqarah, then al-Nisa\u2019, then Al \u2018Imran, slowly, and when he passed a verse of praise, he praised; of request, he requested; of refuge, he sought refuge (Sahih Muslim).'] },
      { h: 'Food and clothing', t: ['Abu Hurayrah said: "The Messenger of Allah \uFDFA never criticised any food. If he liked it, he ate it, and if he disliked it, he left it." (Sahih al-Bukhari and Sahih Muslim). \u2018A\u2019ishah said that sometimes a month passed in which no fire was lit in the Prophet\u2019s \uFDFA household; they lived on dates and water (Sahih al-Bukhari and Sahih Muslim). \u2018Umar entered and saw him lying on a straw mat whose marks were on his side, with only a pillow of palm fibre and a skin hanging on the wall. \u2018Umar wept, and the Prophet \uFDFA said: "Are you not content that for them is this world and for us is the Hereafter?" (Sahih al-Bukhari and Sahih Muslim)'] },
      { h: 'Humour and smiling', t: ['Jarir ibn \u2018Abdullah said: "The Messenger of Allah \uFDFA never veiled himself from me since I accepted Islam, and he never saw me without smiling." (Sahih al-Bukhari and Sahih Muslim). He joked and said only the truth. He once said to Anas, "O you of the two ears." (Sunan Abi Dawud and al-Tirmidhi). A man asked him for a mount; he said, "I will give you a baby of a she-camel." The man said, "What will I do with it?" He said: "Is there any camel which is not the baby of a she-camel?" (Sunan Abi Dawud and al-Tirmidhi). The Companions once asked: "O Messenger of Allah, do you joke with us?" He said: "Yes, but I only say what is true." (Sunan al-Tirmidhi)'] },
      { h: 'With people', t: ['Anas said that if a person took his hand, he did not withdraw it until the person did; if someone spoke to him, he listened until they finished; a slave woman could take him by the hand and lead him where she wanted (Sahih al-Bukhari). He sat on the ground, ate on the ground and said: "I am only a servant. I eat as a servant eats, and sit as a servant sits." (Musnad Ahmad and Ibn Sa\u2019d). When he came to a gathering, he sat wherever there was room.'] },
    ] });

addStory({ id: 'sira-animals', shelf: 'sira', ord: 23.3, title: 'Mercy to animals and the earth', ar: 'الرفق بالحيوان', era: 'Madinah',
  p: ['The Prophet \uFDFA taught that kindness to animals can earn forgiveness, and cruelty can earn punishment. A man forgiven for giving water to a thirsty dog; a woman punished for locking up a cat.', 'He told people not to overload their camels, to sharpen the knife before slaughtering, and not to burn an ants\u2019 nest.'],
  l: ['Mercy extends beyond people to all creatures.', 'Whatever has a moist liver has a reward in kindness.', 'Trees and water are a trust, not only a resource.'],
  src: 'Sahih al-Bukhari, Sahih Muslim, Sunan Abi Dawud' },
  { facts: [['Dog and the well', 'A man forgiven for giving a thirsty dog water (Sahih al-Bukhari and Sahih Muslim)'], ['The cat', 'A woman entered the Fire for imprisoning a cat (Sahih al-Bukhari and Sahih Muslim)'], ['The camel', 'A camel complained to him about being overworked (Sunan Abi Dawud)'], ['The ants', 'Burning a colony is not allowed (Sahih al-Bukhari and Sahih Muslim)'], ['Principle', '"There is a reward in every living creature" (Sahih al-Bukhari and Sahih Muslim)']],
    s: [
      { h: 'The thirsty dog', t: ['The Prophet \uFDFA said: "While a man was walking along a road, he became extremely thirsty. He found a well, went down, drank, and came out. Suddenly he saw a dog panting and eating mud out of thirst. He said: This dog has reached the same thirst that I had. So he went down into the well, filled his shoe with water, held it in his mouth, climbed up and gave the dog a drink. Allah thanked him and forgave him." The Companions asked: "O Messenger of Allah, is there a reward for us in serving animals?" He said: "In every living creature, there is a reward." (Sahih al-Bukhari and Sahih Muslim)'] },
      { h: 'The cat', t: ['He said: "A woman was punished because of a cat which she had tied up until it died; she did not feed it or give it water, or let it eat from the vermin of the earth." (Sahih al-Bukhari and Sahih Muslim).'] },
      { h: 'The camel and the sparrow', t: ['\u2018Abdullah ibn Ja\u2019far narrated that the Prophet \uFDFA entered the garden of an Ansari man, and there was a camel; when it saw him it groaned and its eyes filled with tears. He went to it, wiped behind its ears and it was quiet. He said: "Who owns this camel?" A young Ansari said: "Me, O Messenger of Allah." He said: "Do you not fear Allah regarding this animal that Allah has given you? It complained to me that you starve it and overwork it." (Sunan Abi Dawud, sound)',
        'On a journey, a Companion took the chicks of a hummarah bird, and the mother bird came, beating her wings over the Prophet \uFDFA. He said: "Who has upset this bird by taking her chicks? Return them to her." And when he saw an ant colony that had been burnt, he asked who had burnt it; and he said: "It is not appropriate that anyone punishes with fire except the Lord of the fire." (Sunan Abi Dawud, sound)'] },
      { h: 'The earth', t: ['Planting is charity (Sahih Muslim). He said: "If the Hour is established while one of you has a sapling in his hand, if he can plant it before the Hour comes, let him plant it." (Musnad Ahmad, sound). He taught moderation in the use of water, even for wudu (Sunan Abi Dawud).'] },
    ] });

// ---------------------------------------------------------------- Companions and moments
addStory({ id: 'c-hamza', shelf: 'companions', title: 'Hamzah, the lion of Allah', ar: 'حمزة بن عبد المطلب',
  p: ['Hamzah was the Prophet\u2019s \uFDFA uncle and foster brother, and one of the strongest men in Makkah. He accepted Islam after hearing that Abu Jahl had insulted the Prophet \uFDFA, and went to the Kaaba and struck Abu Jahl on the head with his bow.', 'He fought at Badr and was killed at Uhud by Wahshi. The Prophet \uFDFA called him the master of the martyrs.'],
  l: ['His Islam began in defence of someone dear and grew into conviction.', 'The Prophet \uFDFA wept for him, and was never as sad as on that day.', 'Wahshi\u2019s later repentance showed that Islam forgave even this.'],
  src: 'Sahih al-Bukhari; Sira' },
  { facts: [['Relation', 'Uncle, foster-brother and age-mate of the Prophet \uFDFA'], ['Accepted Islam', 'About the 6th year of prophethood (as reported in the Sira)'], ['Titles', '"Asad Allah" (lion of Allah) and "Sayyid al-Shuhada\u2019" (master of the martyrs)'], ['Killed', 'Uhud, by Wahshi ibn Harb'], ['Buried', 'At Uhud, with \u2018Abdullah ibn Jahsh']],
    s: [
      { h: 'How he became Muslim', t: ['The Sira says that Abu Jahl met the Prophet \uFDFA at Safa, insulted him and struck him, and the Prophet \uFDFA did not answer. A servant of \u2018Abdullah ibn Jud\u2019an saw it. When Hamzah returned from hunting, still carrying his bow, she told him. He went to the Kaaba, found Abu Jahl among Quraysh and hit him on the head with the bow, saying: "Do you insult him when I am on his religion, saying what he says? Hit me back if you can." Banu Makhzum rose to help Abu Jahl, but he told them to leave Hamzah, "for I did insult his nephew badly." Hamzah then reflected, and accepted Islam sincerely; his strength gave the Muslims more confidence.'] },
      { h: 'Badr and Uhud', t: ['At Badr, he fought in the front, and wore an ostrich feather as a mark; he killed Shaybah ibn Rabi\u2019ah in the duel. The Quraysh lost people who were dear to Wahshi\u2019s master, and Jubayr ibn Mut\u2018im promised Wahshi freedom if he killed Hamzah in revenge for his uncle. At Uhud, Wahshi hid behind a rock and threw his spear. Wahshi himself narrated it: "Hamzah was like a grey camel, cutting through the people with his sword... I hid behind a rock and threw; the spear went through his lower abdomen and came out between his legs." (Sahih al-Bukhari)',
        'Hind bint \u2018Utbah mutilated his body, and the Prophet \uFDFA, seeing it, was moved, saying: "I have never stood in a place that angered me more than this." He said that if it were not that Safiyyah (Hamzah\u2019s sister) would be grieved, he would leave him for the beasts. He wept so much that the Companions heard his sobbing, and he buried him with \u2018Abdullah ibn Jahsh in one grave (as reported in the Sira).'] },
      { h: 'Wahshi\u2019s repentance', t: ['After the conquest of Makkah, Wahshi fled to Ta\u2019if; when the Thaqif delegation went to Madinah, he was told that the Prophet \uFDFA does not kill envoys. He came, and said the shahadah. The Prophet \uFDFA asked him how he killed Hamzah, and when he told him, he said: "Can you not hide your face from me?" Wahshi said he used to leave when he saw him. Later, Wahshi killed Musaylimah the liar at Yamamah with the same spear, and he said: "I hope that this atones for killing Hamzah." (Sahih al-Bukhari)'] },
    ] });

addStory({ id: 'c-khalid', shelf: 'companions', title: 'Khalid ibn al-Walid, the sword of Allah', ar: 'خالد بن الوليد',
  p: ['Khalid was the great cavalry commander of Quraysh and the one who turned the tide at Uhud. He became Muslim after Hudaybiyyah and fought at Mu\u2019tah, where the Prophet \uFDFA called him "a sword among the swords of Allah."', 'Under Abu Bakr and \u2018Umar he led the Muslim armies in Iraq and Syria and was never defeated in battle.'],
  l: ['A man who was an enemy became a defender once the truth reached him.', 'Talent used for the cause finds its place.', 'He asked for martyrdom and died in his bed. He said it was a test of sincerity.'],
  src: 'Sahih al-Bukhari; Sira' },
  { facts: [['Accepted Islam', 'About 7\u20138 AH (629 CE)'], ['Title', 'Sayf Allah al-Maslul (the drawn sword of Allah)'], ['Famous for', 'Mu\u2019tah, Yamamah, Iraq, Yarmuk'], ['Never', 'Lost a battle as commander'], ['Died', 'Homs, 21 AH']],
    s: [
      { h: 'Before Islam', t: ['As a young man of Banu Makhzum, Khalid inherited the cavalry command of Quraysh. He led the charge around the flank of the archers at Uhud and had a role in the pursuit of Muslims. At Hudaybiyyah he was sent to stop the Muslims and saw them praying Zuhr, and said, "They were off guard; we could have attacked." He is reported to have said: "I saw that this man is protected." Then, in his own account, he reflected: "Where could I go? To the Negus? To Heraclius? To the Persians? And live among the Arabs as an inferior?"'] },
      { h: 'The decision', t: ['He travelled to Madinah, together with \u2018Amr ibn al-\u2018As and \u2018Uthman ibn Talhah, and accepted Islam. The Prophet \uFDFA welcomed him: "Praise be to Allah who guided you; I have seen in you intelligence which I hoped would lead you to what is good." Khalid asked the Prophet \uFDFA to pray for forgiveness for all that he had done in opposing him. He said: "Islam wipes out what came before it." (as reported in the Sira)'] },
      { h: 'The sword of Allah', t: ['At Mu\u2019tah, after the three commanders fell, the Muslims chose Khalid and he saved the army (see the account of Mu\u2019tah). The Prophet \uFDFA said: "The banner was taken by a sword from among the swords of Allah." (Sahih al-Bukhari). Under Abu Bakr, he put down the apostate Musaylimah at Yamamah and led an army to Iraq, and then marched across the Syrian desert in a famous forced march to reach the front at Yarmuk. Under \u2018Umar, he was removed from command, which he accepted without complaint, saying: "I fight for Allah, not for \u2018Umar," and served as a soldier.'] },
      { h: 'The end', t: ['On his deathbed in Homs, he is reported to have said: "I have fought in so many battles, and there is no place on my body without a scar from a sword, a spear or an arrow, and here I am dying in my bed like a camel. May the eyes of the cowards not sleep." He left his horse and weapons as charity in the cause of Allah. It is reported that \u2018Umar wept for him and said: "Women will never give birth to the like of Khalid."'] },
    ] });

addStory({ id: 'c-abu-dharr', shelf: 'companions', title: 'Abu Dharr al-Ghifari', ar: 'أبو ذر الغفاري',
  p: ['Abu Dharr lived among the tribe of Ghifar, who were highway robbers. Hearing of a man in Makkah claiming to be a prophet, he sent his brother to investigate and then went himself, stayed in the Sacred Mosque for days, and lived on Zamzam water until he met the Prophet \uFDFA.', 'He accepted Islam, declared it in the mosque and was beaten by Quraysh. He is remembered for plain living, truthfulness and for always speaking the truth to those in power.'],
  l: ['The search for the truth is worth a long journey.', 'Zamzam was his food for a month. He said he grew fat and felt no hunger.', 'The Prophet \uFDFA told him to love the poor and speak the truth, even if bitter.'],
  src: 'Sahih Muslim; Sahih al-Bukhari' },
  { facts: [['Tribe', 'Ghifar, near the road between Makkah and Syria'], ['Accepted Islam', 'Early, said to be the fourth or fifth to do so'], ['Famous for', 'Asceticism and truthfulness'], ['Died', 'Al-Rabadhah, 32 AH, alone with his family'], ['Prophet\u2019s words', '"No one under the sky is more truthful than Abu Dharr" (al-Tirmidhi)']],
    s: [
      { h: 'The search', t: ['He told Ibn \u2018Abbas his own story (Sahih Muslim): "We were from Ghifar. I heard that a man had appeared in Makkah claiming to be a prophet. I told my brother Unays: Go to this man and bring me news. He went, came back and said: I saw him enjoining good character, and saying words that are not poetry. I said: You have not satisfied me. So I took a water skin and a bag of provisions and went to Makkah. I did not know him and did not want to ask anyone. I drank Zamzam and stayed in the mosque."',
        '\u2018Ali saw him and took him to his home as a guest, without asking anything. The next day too. On the third day, \u2018Ali asked what brought him. When Abu Dharr asked him to promise secrecy, he told him. \u2018Ali said: "It is true, he is the Messenger of Allah. When you wake, follow me; if I see anything that worries me, I will stop as if to relieve myself, and if I walk on, follow me." He followed \u2018Ali, entered the Prophet\u2019s \uFDFA place, and said: "Peace be upon you, Messenger of Allah." The Prophet \uFDFA responded and he accepted Islam.'] },
      { h: 'In the mosque', t: ['The Prophet \uFDFA said: "Go back to your people, tell them, until you hear that we have prevailed." Abu Dharr said: "By the One who has your soul, I will proclaim it among them." He went to the mosque and shouted: "I bear witness that there is no god but Allah and that Muhammad is the Messenger of Allah." The Quraysh rose and beat him until he fell. Al-\u2018Abbas, the Prophet\u2019s \uFDFA uncle, reached him and said: "Woe to you! Do you not know that he is of Ghifar, and your trade route to Syria passes through them?" They left him. The next day he did the same, and was beaten again, and al-\u2018Abbas saved him (Sahih Muslim). Then he returned to his people and invited them, and his tribe and the neighbours of Aslam accepted Islam.'] },
      { h: 'His simplicity', t: ['The Prophet \uFDFA once advised him: "O Abu Dharr, I see you are weak, and I love for you what I love for myself. Do not take charge of even two people, and do not take care of an orphan\u2019s property." (Sahih Muslim). He lived in the desert settlement of al-Rabadhah, and warned the wealthy about hoarding. In the time of \u2018Uthman, he expressed his views strongly. He died there in 32 AH, with only his wife and a servant, and as the Prophet \uFDFA had foretold, a group of believers travelling from Iraq, among them \u2018Abdullah ibn Mas\u2019ud, passed by and buried him (Musnad Ahmad).'] },
    ] });

addStory({ id: 'c-abu-hurayra', shelf: 'companions', title: 'Abu Hurayrah and the memory of the hadith', ar: 'أبو هريرة',
  p: ['Abu Hurayrah came from the tribe of Daws in Yemen and accepted Islam in 7 AH at Khaybar. He stayed in the Prophet\u2019s \uFDFA mosque as one of the people of the Suffah, living on whatever people shared, and learned by sitting with him.', 'He prayed for his memory, and it did not fail him. He narrated more hadith than any other Companion.'],
  l: ['Hunger and poverty did not stop him from learning.', 'His kindness to his mother is also a lesson.', 'The Prophet \uFDFA gave him a name from a small cat he carried.'],
  src: 'Sahih al-Bukhari and Sahih Muslim (his own accounts)' },
  { facts: [['Name', '\u2018Abd al-Rahman ibn Sakhr al-Dawsi, called Abu Hurayrah (father of the kitten)'], ['Accepted Islam', '7 AH, then stayed with the Prophet \uFDFA about three years'], ['Hadith narrated', 'About 5,374 (as commonly counted)'], ['Students', 'Over eight hundred'], ['Died', 'Madinah, c. 58 AH']],
    s: [
      { h: 'Learning through hunger', t: ['He said: "You say that Abu Hurayrah narrates a lot from the Prophet \uFDFA. Allah is the Appointed Time. The Muhajirun were busy with trade in the markets, and the Ansar with their fields, and Abu Hurayrah stayed with the Prophet \uFDFA to fill his stomach and attended when others were absent, and remembered when they forgot." (Sahih al-Bukhari and Sahih Muslim). He once fell down in the mosque from hunger and people thought he was mad. Abu Bakr and \u2018Umar passed by and did not understand his hint when he asked about a verse. Then the Prophet \uFDFA came, knew from his face, said "Abu Hirr," and took him home and found a bowl of milk. He told him to call the people of the Suffah, and then to hand it to each of them until all had drunk, and last of all, he drank and the Prophet \uFDFA drank. (Sahih al-Bukhari)'] },
      { h: 'The cloak', t: ['He said to the Prophet \uFDFA: "I hear many hadith from you and forget them." He said: "Spread your cloak." He spread it, the Prophet \uFDFA made a gesture as if scooping and putting something in it, and said: "Gather it." He gathered it, and said: "I never forgot anything after that." (Sahih al-Bukhari and Sahih Muslim)'] },
      { h: 'His mother', t: ['His mother was an idolater, and he invited her to Islam every day. One day she said something about the Prophet \uFDFA that grieved him, and he went in tears: "O Messenger of Allah, I invite my mother to Islam, and she refuses, and today I invited her and she said what I dislike. Pray to Allah to guide the mother of Abu Hurayrah." The Prophet \uFDFA said: "O Allah, guide Abu Hurayrah\u2019s mother." He ran back, heard water running, and when he entered, she said the shahadah. He went back weeping with joy and asked the Prophet \uFDFA to pray that Allah make him and his mother beloved to the believers. (Sahih Muslim)'] },
    ] });

addStory({ id: 'c-asma', shelf: 'companions', title: 'Asma\u2019 bint Abi Bakr, she of the two belts', ar: 'أسماء بنت أبي بكر',
  p: ['Asma\u2019 was the elder daughter of Abu Bakr and the sister of \u2018A\u2019ishah. On the night of the Hijrah, she brought food for the Prophet \uFDFA and her father in the cave of Thawr, and tore her waist-belt in two to tie the bag and the water skin. The Prophet \uFDFA called her "the one with the two belts."', 'She emigrated while pregnant and gave birth in Quba to \u2018Abdullah ibn al-Zubayr, the first Muslim baby born in Madinah.'],
  l: ['Courage in a woman or a girl can carry a whole mission.', 'She stood up to Abu Jahl when he asked about her father.', 'She stayed steady as her son was killed: "Faith is not shaken."'],
  src: 'Sahih al-Bukhari (Hijrah account, Asma\u2019 narrates)' },
  { facts: [['Born', 'About 27 years before the Hijrah, so about ten years older than \u2018A\u2019ishah'], ['Husband', 'Al-Zubayr ibn al-\u2018Awwam, one of the ten promised Paradise'], ['Son', '\u2018Abdullah ibn al-Zubayr'], ['Died', 'Makkah, 73 AH, at about 100'], ['Title', 'Dhat al-Nitaqayn']],
    s: [
      { h: 'The night of the Hijrah', t: ['She narrates (Sahih al-Bukhari): "I prepared the provisions for the Prophet \uFDFA and Abu Bakr when they intended to leave for Madinah. I found nothing to tie the bag with, nor the water skin. I said to Abu Bakr: By Allah, I find nothing to tie it with except my waist-belt. He said: Split it in two, and tie the water skin with one and the bag with the other. I did, and that is why I was called Dhat al-Nitaqayn." She also came to the cave with food each evening.',
        'Her grandfather, Abu Quhafah, who was old and blind and not yet Muslim, came when they left and said: "I think he has caused you grief by taking his money with him." She said: "No, grandfather, he left us a lot of good." She put pebbles in the niche where her father used to keep his money and covered it with a cloth, and put his hand on it to reassure him. He said: "If he has left it to you, he has done well." She said: "By Allah, he left us nothing, but I wanted to calm the old man."'] },
      { h: 'Abu Jahl', t: ['When Abu Jahl and some men came to her door asking where her father was, she said: "By Allah, I do not know where my father is." Abu Jahl slapped her on the cheek so hard that her earring flew off (Sira). She did not tell.'] },
      { h: 'A hard-working home', t: ['She said (Sahih al-Bukhari and Sahih Muslim): "When al-Zubayr married me, he had no wealth or land or slave, nothing but his horse. I used to feed his horse, take care of it, grind the date stones for it and fetch water. I carried date stones on my head from al-Zubayr\u2019s land that the Prophet \uFDFA had given him, about two miles away. One day, I was carrying them, and I met the Prophet \uFDFA with some of the Ansar. He called me and made his camel kneel to take me behind him. I was shy to go with the men and remembered al-Zubayr and his jealousy. He understood and went on." When she told al-Zubayr, he said that carrying the stones was harder for him than her riding with the Prophet \uFDFA. Later Abu Bakr sent her a servant to take care of the horse, and she said: "It was as if he freed me."'] },
      { h: 'Her last years', t: ['Her son \u2018Abdullah ibn al-Zubayr held Makkah against the Umayyad governor al-Hajjaj in 73 AH. Before the last battle, he came to his mother, who was blind and very old, and told her that his men were deserting. She said: "You know yourself best. If you are on the truth and calling to the truth, go on until you die for it; do not let the children of Umayyah play with you. If you wanted this world, you are a poor servant." He fought and was killed. She was told to be patient; she said: "How would I not be patient after he gave his life for Allah?" She died soon afterwards, a few days later, at around a hundred years old, with no tooth lost and no thought failing.'] },
    ] });

addStory({ id: 'c-fatima', shelf: 'companions', title: 'Fatimah, the daughter of the Prophet \uFDFA', ar: 'فاطمة الزهراء',
  p: ['Fatimah was the youngest daughter of the Prophet \uFDFA and Khadijah, wife of \u2018Ali and mother of al-Hasan and al-Husayn. She was in Makkah in the worst years and cleaned the Prophet\u2019s \uFDFA back when Quraysh threw camel entrails on him.', 'In Madinah she lived in poverty. When her hands hurt from grinding grain, she asked her father for a servant and he taught her instead a dhikr, tasbih of Fatimah.'],
  l: ['A great person\u2019s daughter lived in hardship by choice.', 'The dhikr he gave her is better than a servant.', 'He called her "a part of me."'],
  src: 'Sahih al-Bukhari and Sahih Muslim' },
  { facts: [['Born', 'Makkah, before the revelation (about 5 years before, in some accounts)'], ['Husband', '\u2018Ali ibn Abi Talib'], ['Children', 'Al-Hasan, al-Husayn, Zaynab, Umm Kulthum'], ['Titles', 'Al-Zahra\u2019, Sayyidat nisa\u2019 ahl al-Jannah'], ['Died', 'About six months after the Prophet \uFDFA, in Ramadan 11 AH']],
    s: [
      { h: 'In Makkah', t: ['As a young girl, she saw the persecution first-hand. When the Prophet \uFDFA was praying at the Kaaba and Quraysh leaders threw the entrails of a camel on his back, it was Fatimah who came running, removed it, and scolded them (Sahih al-Bukhari). She also looked after her mother in her final days and in the hardship of the boycott.'] },
      { h: 'The grinding stone and the tasbih', t: ['\u2018Ali narrates (Sahih al-Bukhari and Sahih Muslim): "Fatimah complained of the effect of the grinding stone on her hands. She heard that some captives had been brought to the Prophet \uFDFA, so she went to ask for a servant but did not find him; she told \u2018A\u2019ishah. When the Prophet \uFDFA came, \u2018A\u2019ishah told him. He came to us when we had gone to bed. We started to get up, but he said: Stay where you are. He sat between us until I felt the coolness of his feet on my stomach. He said: Shall I not tell you of something better than what you asked for? When you go to bed, say Allahu akbar thirty-four times, Subhan Allah thirty-three times and Alhamdulillah thirty-three times. That is better for you than a servant." \u2018Ali said: "I have never left it since I heard it from the Prophet \uFDFA." Someone asked, "Not even on the night of Siffin?" He said, "Not even on the night of Siffin."'] },
      { h: 'A part of me', t: ['The Prophet \uFDFA said: "Fatimah is a part of me, so whoever angers her angers me." (Sahih al-Bukhari and Sahih Muslim). When she entered, he would stand, take her hand, kiss her and seat her in his place. In his final illness, he whispered to her; she wept; then he whispered again and she laughed. \u2018A\u2019ishah asked why, and Fatimah said later: "He told me he would die in this illness, so I wept; then he told me that I would be the first of his family to join him, so I laughed." (Sahih al-Bukhari and Sahih Muslim). She died about six months after him.'] },
    ] });

addStory({ id: 'c-zayd', shelf: 'companions', title: 'Zayd ibn Harithah, the beloved', ar: 'زيد بن حارثة',
  p: ['Zayd was captured as a boy in a raid, sold as a slave in Makkah and ended up in the service of Khadijah, who gave him to the Prophet \uFDFA. When his father and uncle came to pay a ransom and take him home, the Prophet \uFDFA let Zayd choose. Zayd said: "I will not prefer anyone to you."', 'The Prophet \uFDFA freed him and announced that he was his son. Zayd is the only Companion named in the Qur\u2019an.'],
  l: ['Love and good treatment can make a person choose servitude with the right master over freedom among his own.', 'Islam raised a former slave to be a general.', 'The Prophet \uFDFA loved him and his son Usamah.'],
  v: [[33, 37]], src: 'Sira; Sahih al-Bukhari; Qur\u2019an 33:37' },
  { facts: [['Born', 'Into the tribe of Kalb, in the Syrian desert'], ['Became Muslim', 'Among the first four or five'], ['Commander', 'Of the army at Mu\u2019tah, where he was killed (8 AH)'], ['Wife', 'Umm Ayman; later Zaynab bint Jahsh (divorced)'], ['Son', 'Usamah ibn Zayd']],
    s: [
      { h: 'Captured', t: ['Zayd, about eight, went with his mother to visit her family when raiders captured him and sold him at \u2018Ukaz. Hakim ibn Hizam bought him for his aunt Khadijah, who gave him to her husband, Muhammad \uFDFA, before the revelation. Zayd\u2019s father Harithah wept and wrote poetry looking for him. Years later, some men of Kalb saw him at Hajj and told his family.'] },
      { h: 'The choice', t: ['Harithah and his brother travelled to Makkah with a ransom. The Prophet \uFDFA said: "Call him and let him choose. If he chooses you, I will not ask for anything; and if he chooses me, then by Allah I am not one to prefer anyone over him." Zayd came, and was asked if he knew these men. He said: "Yes, this is my father and this my uncle." The Prophet \uFDFA said: "You know me, and have seen how I treated you. Choose me or them." Zayd said: "I do not choose anyone over you. You are to me like my father and uncle." They said: "Woe to you, Zayd! You prefer slavery over freedom and your father and uncle?" He said: "Yes, I have seen something in this man that means I would not prefer anyone to him ever." The Prophet \uFDFA took him to the Kaaba and announced: "Be witnesses that Zayd is my son; he inherits from me and I from him." His father and uncle left satisfied. (Sira)'] },
      { h: 'Named in the Qur\u2019an', t: ['After Islam, the practice of adoption making the adopted child a legal son was ended: "Call them by [the names of] their fathers; it is more just in the sight of Allah." (33:5) Then he was called Zayd ibn Harithah again. His marriage to Zaynab bint Jahsh did not last, and Allah then had the Prophet \uFDFA marry her to remove the stigma of marrying a former adopted son\u2019s wife: "So when Zayd had no longer any need for her, We married her to you." (33:37), which names him. \u2018A\u2019ishah said: "If the Prophet \uFDFA had left him alive, he would have appointed him as his successor in the army." (Musnad Ahmad)'] },
      { h: 'Mu\u2019tah', t: ['He led nearly every expedition he was sent on, and died carrying the banner at Mu\u2019tah. The Prophet \uFDFA went to Zayd\u2019s daughter, who wept. He wept too. Sa\u2019d said: "What is this, O Messenger of Allah?" He said: "The longing of the beloved for his beloved." (as reported in the Sira)'] },
    ] });

addStory({ id: 'c-abu-ubayda', shelf: 'companions', title: 'Abu \u2018Ubaydah, the trustworthy one of the ummah', ar: 'أبو عبيدة بن الجراح',
  p: ['Abu \u2018Ubaydah \u2018Amir ibn \u2018Abdullah ibn al-Jarrah was among the first to accept Islam through Abu Bakr and one of the ten promised Paradise. The Prophet \uFDFA said: "Every nation has a trustworthy one, and the trustworthy one of this nation is Abu \u2018Ubaydah ibn al-Jarrah."', 'At Uhud, he pulled out the rings of the Prophet\u2019s \uFDFA helmet with his teeth, losing his front teeth, and was called the best of men for it.'],
  l: ['Trustworthiness can be a title.', 'He was a leader who was modest. Told to command, he refused to take credit.', 'He chose to stay with his men in the plague, and died with them.'],
  src: 'Sahih al-Bukhari and Sahih Muslim' },
  { facts: [['Accepted Islam', 'Early, through Abu Bakr'], ['Title', '"Amin hadhihi al-ummah" (Sahih al-Bukhari)'], ['Famous for', 'The expedition of Sif al-Bahr (the whale), conquest of Syria'], ['Died', 'Plague of \u2018Amwas, 18 AH'], ['Aged', '58']],
    s: [
      { h: 'The army of the whale', t: ['Jabir ibn \u2018Abdullah narrates (Sahih al-Bukhari and Sahih Muslim): the Prophet \uFDFA sent them, three hundred riders, with Abu \u2018Ubaydah as commander, to intercept a Quraysh caravan, and gave them a bag of dates. Abu \u2018Ubaydah gave them one date each day; then it ran out. They were so hungry that they ate leaves until their lips were swollen. Then the sea cast up a creature like a mound, called al-\u2018Anbar. Abu \u2018Ubaydah first said it was carrion, then said: "No, we are the messengers of the Messenger of Allah, and in the way of Allah, and in need; so eat." They stayed there a month, until they became fat. Abu \u2018Ubaydah had them stand a rib of the creature, and the tallest man with the largest camel passed under it without touching. When they returned, the Prophet \uFDFA said: "It is a provision Allah has brought out for you. Do you have any of its flesh to give us?" They sent some, and he ate it.'] },
      { h: 'Character', t: ['When the delegation from Najran asked the Prophet \uFDFA to send them a trustworthy man, he said: "I will send you a truly trustworthy man," and the Companions raised their necks hoping. He said: "Get up, Abu \u2018Ubaydah ibn al-Jarrah." (Sahih al-Bukhari and Sahih Muslim). At Saqifah, when \u2018Umar offered his oath of allegiance, Abu \u2018Ubaydah said he would not take a position above a man the Prophet \uFDFA had put forward to lead the prayer. As commander in Syria he took the surrender of Damascus, and when Heraclius lost, he lived as simply as the ordinary soldier.'] },
      { h: 'The plague', t: ['In 18 AH, the plague of \u2018Amwas spread in Syria. \u2018Umar wrote to Abu \u2018Ubaydah asking him to come to him in Madinah, as he had need of him. Abu \u2018Ubaydah, knowing the reason, wrote: "I know your need. I am among Muslim soldiers and I will not leave them." When \u2018Umar read, he wept. Abu \u2018Ubaydah died of the plague with many others, including Mu\u2019adh ibn Jabal, who succeeded him, and Yazid ibn Abi Sufyan. His last speech to the soldiers: "Praise Allah that the plague is a mercy from your Lord and the death of the righteous before you." Abu \u2018Ubaydah is buried in the Jordan Valley.'] },
    ] });

addStory({ id: 'c-muadh', shelf: 'companions', title: 'Mu\u2019adh ibn Jabal, the scholar of halal and haram', ar: 'معاذ بن جبل',
  p: ['Mu\u2019adh accepted Islam as a young man in Madinah, at the second pledge of \u2018Aqabah. He became one of the greatest scholars among the Companions. The Prophet \uFDFA said: "The most knowledgeable of my nation in halal and haram is Mu\u2019adh ibn Jabal."', 'When he was sent to Yemen as a teacher and judge, the Prophet \uFDFA walked with him to give him advice, and told him: "O Mu\u2019adh, perhaps you will not see me after this year."'],
  l: ['The Prophet \uFDFA told him: "By Allah I love you," and then gave him a dua to say after every prayer.', 'Judgement requires first knowing the Qur\u2019an, then the Sunnah, then reasoning.', 'He taught people to recite and to remember Allah.'],
  src: 'Sunan al-Tirmidhi, Sunan Abi Dawud, Sahih al-Bukhari and Sahih Muslim' },
  { facts: [['Born', 'Madinah, about 20 years before the Hijrah'], ['Role', 'Sent to Yemen as a teacher and judge, 10 AH'], ['Prophet\u2019s love', '"O Mu\u2019adh, by Allah I love you"'], ['Died', 'Plague of \u2018Amwas, 18 AH, aged about 33'], ['Rank', 'On the Day of Resurrection "he will be raised as a leader of scholars" (reported)']],
    s: [
      { h: 'A teacher\u2019s dua', t: ['The Prophet \uFDFA took Mu\u2019adh by the hand and said: "O Mu\u2019adh, by Allah, I love you. So I advise you, O Mu\u2019adh: do not neglect saying at the end of every prayer: Allahumma a\u2019inni \u2018ala dhikrika wa shukrika wa husni \u2018ibadatika (O Allah, help me to remember You, to thank You and to worship You well)." (Sunan Abi Dawud and al-Nasa\u2019i, sound). This is among the most beloved duas for completing prayer.'] },
      { h: 'The journey to Yemen', t: ['The Prophet \uFDFA walked beside Mu\u2019adh\u2019s mount as he left, giving him advice, and said: "Fear Allah wherever you are; follow a bad deed with a good deed, which will erase it; and treat people with good character." (Sunan al-Tirmidhi). He said: "Make things easy and do not make them hard." He told him to teach first the oneness of Allah, and he warned him against taking the best of their property in zakah and against the dua of the oppressed (Sahih al-Bukhari and Sahih Muslim).',
        'A report in Sunan Abi Dawud and al-Tirmidhi tells that when asked by what he would judge, Mu\u2019adh said: "By the Book of Allah." "And if you do not find it?" "By the Sunnah of the Messenger of Allah." "And if you do not find it?" "I will strive to form my own opinion, and not fall short." The Prophet \uFDFA patted his chest and said: "Praise be to Allah who has made the messenger of the Messenger of Allah agree with what pleases Him." The chain of this report is disputed among scholars, but its meaning is accepted.'] },
      { h: 'A man of long prayers', t: ['Once, he led his people in prayer after praying with the Prophet \uFDFA, and recited al-Baqarah. A man left the prayer and prayed alone. Mu\u2019adh was told and called him a hypocrite. The man complained to the Prophet \uFDFA, who said: "O Mu\u2019adh, are you putting people to trial? Recite al-Shams, al-Duha, al-Layl, al-A\u2019la." (Sahih al-Bukhari and Sahih Muslim). It is an example of a great scholar being corrected gently about the needs of those praying behind him.'] },
    ] });

addStory({ id: 'c-suhayb', shelf: 'companions', title: 'Suhayb al-Rumi, the profitable trade', ar: 'صهيب الرومي',
  p: ['Suhayb was a Byzantine-born man raised among Arabs, who became rich in Makkah. When he decided to emigrate to Madinah, Quraysh stopped him and said that he had come with nothing and would not leave with wealth. He gave them all his possessions in return for being allowed to go.', 'The Prophet \uFDFA, when he heard, is reported to have said: "Profitable trade, Abu Yahya!" and verse 2:207 is said to have been revealed about him.'],
  l: ['Faith is worth everything a person owns.', 'He was the narrator of the story of the trench and the boy, which shows a man with faith remembered what faith costs.', '\u2018Umar chose him to lead the prayer at his funeral.'],
  v: [[2, 207]], src: 'Sira; al-Hakim; Sahih Muslim (Suhayb narrates the boy and the king)' },
  { facts: [['Origin', 'Born near Mosul; taken captive by the Byzantines, then sold to Makkah'], ['Nickname', 'Abu Yahya'], ['Narrated', 'The story of the boy and the king in Sahih Muslim'], ['Died', 'Madinah, 38 AH, aged about 70'], ['Honour', '\u2018Umar appointed him to lead the prayer after him']],
    s: [
      { h: 'The wealth', t: ['He had been taken as a boy and grew up speaking Arabic with a Roman accent, which is why he was called al-Rumi. He became rich as a trader. When he said he would emigrate, the people of Makkah told him: "You came to us poor and with nothing, and now you have your wealth. By Allah, you will not leave with it." He said: "If I give you my wealth, will you let me go?" They said: "Yes." He gave them everything. (as reported in the Sira)'] },
      { h: 'The Prophet\u2019s response', t: ['When he arrived at Quba, the Prophet \uFDFA saw him and said: "The trade has profited, Abu Yahya," twice, and it is reported that Allah revealed: "And among the people is he who sells himself, seeking the approval of Allah. And Allah is kind to [His] servants." (2:207) (al-Hakim and others; some scholars grade the chain as weak, others as sound by corroboration).'] },
      { h: 'Later years', t: ['He was known for his generosity: he would feed people until \u2018Umar once told him: "I have heard that you give too much food away." He said: "The Prophet \uFDFA said: The best of you are those who feed food and return the greeting." (Musnad Ahmad). When \u2018Umar was stabbed, he told the people to wait for six men to choose a successor, and told Suhayb to lead the prayers for the community for the three days it took.',
        'Suhayb narrated the long hadith of the boy, the king, the sorcerer and the monk (Sahih Muslim), which had in it all that he, an ex-captive, had understood about steadfastness.'] },
    ] });

addStory({ id: 's-thumama', shelf: 'situations', title: 'Thumamah, tied to the pillar', ar: 'ثمامة بن أثال',
  p: ['The Prophet \uFDFA\u2019s horsemen captured a man and brought him to the mosque, tying him to a pillar. It was Thumamah ibn Uthal, chief of Banu Hanifah, who had been an enemy. The Prophet \uFDFA asked: "What do you have, Thumamah?" He said: "Good, O Muhammad. If you kill me, you kill a man of blood; if you pardon, you pardon one who is thankful; if you want wealth, ask and you will get it."', 'For three days, the Prophet \uFDFA asked and he gave the same answer. Then he said: "Release Thumamah." He went to a palm grove, washed and returned, and said: "I bear witness that there is no god but Allah and that Muhammad is His Messenger."'],
  l: ['The Prophet \uFDFA treated a prisoner with dignity in his own mosque.', 'Kindness changed Thumamah from the person he hated most to the person he loved most.', 'Thumamah protected Muslims later by refusing Makkah grain.'],
  src: 'Sahih al-Bukhari and Sahih Muslim (Abu Hurayrah)' },
  { facts: [['Narrated by', 'Abu Hurayrah'], ['Who', 'Thumamah ibn Uthal al-Hanafi, chief of Yamamah'], ['Where held', 'Tied to a pillar of the Prophet\u2019s Mosque'], ['Days', 'Three'], ['After', 'He stopped grain going to Makkah until the Prophet \uFDFA permitted it']],
    s: [
      { h: 'The captive', t: ['Abu Hurayrah narrates: "The Prophet \uFDFA sent horsemen toward Najd and they brought a man from Banu Hanifah called Thumamah ibn Uthal, the chief of Yamamah. They tied him to one of the pillars of the mosque. The Prophet \uFDFA went to him and said: What do you have, O Thumamah? He said: I have good, O Muhammad. If you kill me, you will kill someone with blood owed; if you show favour, you will favour a thankful man; and if you want wealth, ask and you will be given what you want. The Prophet \uFDFA left him. The next day he asked: What do you have, Thumamah? He said: As I told you, if you show favour you will favour a grateful man. He left him until the day after, and asked again. He said: What I told you. The Prophet \uFDFA said: Release Thumamah."'] },
      { h: 'The conversion', t: ['"He went to a date grove near the mosque, washed, and came into the mosque. He said: I bear witness that there is no god except Allah and I bear witness that Muhammad is the Messenger of Allah. O Muhammad, by Allah, there was no face on earth more hateful to me than your face, and now your face is the most beloved of faces to me. By Allah, there was no religion more hateful to me than your religion, and now your religion is the most beloved of religions to me. And no city was more hateful to me than yours, and now yours is the most beloved of cities to me. Your cavalry took me while I was intending \u2018umrah. What do you think? The Prophet \uFDFA gave him good news and told him to perform \u2018umrah." (Sahih al-Bukhari and Sahih Muslim)'] },
      { h: 'In Makkah', t: ['When he reached Makkah, someone said: "Have you become a Sabian (left your religion)?" He said: "No, I have accepted Islam with Muhammad. And no, by Allah, not a grain of wheat will reach you from Yamamah unless the Prophet \uFDFA permits it." Yamamah was Makkah\u2019s grain supplier. Quraysh wrote to the Prophet \uFDFA, begging him in the name of kinship to tell Thumamah to let the grain through, and he did. The man whom Quraysh had considered an enemy of Muhammad became a friend who was able to help them because the Prophet \uFDFA was merciful.'] },
    ] });

addStory({ id: 's-adi', shelf: 'situations', title: 'Hatim\u2019s daughter and her brother \u2018Adi', ar: 'سفانة بنت حاتم',
  p: ['After a raid on the tribe of Tayy, the Muslims captured the daughter of Hatim al-Ta\u2019i, who was famed for generosity. She stood before the Prophet \uFDFA and said: "My father has died and the one who looked after me is absent. Do me a favour, and Allah will favour you." The Prophet \uFDFA freed her, gave her clothes and travel money, and sent her to her people.', 'She found her brother \u2018Adi, a Christian chieftain who had fled to Syria, and told him what she had seen. He went to meet the Prophet \uFDFA and became a Muslim.'],
  l: ['Good treatment of a woman prisoner opened a chieftain\u2019s heart.', 'The Prophet \uFDFA honoured her as the daughter of a generous man.', '\u2018Adi\u2019s conversion shows how stories of the Prophet\u2019s \uFDFA conduct spread.'],
  src: 'Sira of Ibn Ishaq; Sunan al-Tirmidhi (\u2018Adi on 9:31); Sahih al-Bukhari (\u2018Adi\u2019s words on the Hajj and the lady of Hira)' },
  { facts: [['Who', 'Safanah (or Sufanah), daughter of Hatim al-Ta\u2019i, and her brother \u2018Adi'], ['When', '9 AH, after a raid on Tayy'], ['Her request', '"Grant me a favour, and may Allah grant you one"'], ['\u2018Adi', 'Accepted Islam and was among those who defended the faith after the Prophet \uFDFA'], ['Prophet\u2019s words', '"Her father loved noble character"']],
    s: [
      { h: 'The captive woman', t: ['As the Sira tells, the women and children of Tayy were brought to Madinah after \u2018Ali led a raid on the tribe, and housed near the mosque. Hatim\u2019s daughter said: "O Messenger of Allah, my father has died, and the one who would help me is absent. Be kind to me, and may Allah be kind to you. I am the daughter of the chief of his people, who used to free captives, feed people, spread peace and fulfil needs, and never turned away a person in need. I am the daughter of Hatim al-Ta\u2019i." The Prophet \uFDFA said: "O girl, this is the character of the believers. If your father had been a Muslim, I would have asked for mercy on him. Free her, for her father loved noble character, and Allah loves noble character." She was freed.'] },
      { h: 'Her brother', t: ['She waited until a caravan from her people was going to Syria, and with the Prophet\u2019s \uFDFA help, travelled with them. She found her brother \u2018Adi and said: "You have wronged your family by fleeing and leaving your family behind. Go to him quickly. By Allah, I have seen from him what I do not think any other would do." \u2018Adi came to Madinah. The Prophet \uFDFA took him to his house, offered him a cushion and sat on the ground. \u2018Adi said: "By Allah, this is not the manner of a king." The Prophet \uFDFA addressed him as a leader, and spoke of how many people would come to Islam, and how a woman would travel from al-Hirah to Makkah fearing none but Allah. \u2018Adi accepted Islam. Later, he said he had seen the first and second come true: "the lady from Hirah" and that the treasures of Persia were opened (Sahih al-Bukhari).'] },
    ] });

// order and numbering for the Sira shelf (existing entries keep their order; new ones carry an explicit position)
DISCOVER.stories.forEach((s) => { if (s.ord == null && s.n != null) s.ord = s.n; });
